(function () {
  // Quy tắc đặt tên dữ liệu thử: <tiền tố>_<mã TC>_<mã lượt chạy>. Mã lượt chạy gồm các chữ cái tăng dần, mỗi chữ theo sau là
  // số thứ tự của nó trong bảng chữ cái (a1b2c3d4, D4E5G7K11), lấy theo phút chạy. Số chữ cái chỉnh bằng biến aa_code_letters (mặc định 4).
  function binom(n, k) { if (k < 0 || k > n) { return 0; } var r = 1; for (var i = 1; i <= k; i++) { r = r * (n - k + i) / i; } return Math.round(r); }
  function unrank(idx, n, k) {
    var out = [], start = 0;
    for (var i = 0; i < k; i++) {
      for (var c = start; c < n; c++) { var cnt = binom(n - c - 1, k - i - 1); if (idx < cnt) { out.push(c); start = c + 1; break; } idx -= cnt; }
    }
    return out;
  }
  function runCode() {
    var K = parseInt(pm.collectionVariables.get('aa_code_letters'), 10) || 4, total = binom(26, K), mi = Math.floor(Date.now() / 60000);
    var upper = Math.floor(mi / total) % 2 === 1;
    return unrank(mi % total, 26, K).map(function (c) { var L = String.fromCharCode(97 + c); return (upper ? L.toUpperCase() : L) + (c + 1); }).join('');
  }
  var seq = 0;
  var aa = {
    base: function () { return pm.variables.replaceIn('{{base_url}}'); },
    uniq: function (p) { seq++; var m = String(pm.info.requestName || '').match(/TC-AA-(\d+)/i); return p + '_TC' + (m ? m[1] : '') + '_' + runCode() + (seq > 1 ? '_' + seq : ''); },
    tokenOf: function (html) {
      var m = html.match(/name=["']csrfmiddlewaretoken["'][^>]*value=["']([^"']+)["']/);
      return m ? m[1] : '';
    },
    get: function (path, cb) {
      pm.sendRequest({ url: aa.base() + path, method: 'GET' }, function (e, r) { cb(r); });
    },
    post: function (path, fields, cb) {
      var body = Object.keys(fields).map(function (k) { return { key: k, value: fields[k] }; });
      pm.sendRequest({ url: aa.base() + path, method: 'POST', body: { mode: 'urlencoded', urlencoded: body } }, function (e, r) { cb(r); });
    },
    // lấy CSRF mới của trang path và lưu vào biến csrf_token
    token: function (path, cb) {
      aa.get(path, function (r) { pm.collectionVariables.set('csrf_token', aa.tokenOf(r.text())); if (cb) { cb(); } });
    },
    // đưa phiên về Guest (đăng xuất nếu đang đăng nhập), rồi lấy CSRF của trang path
    guest: function (path, cb) {
      aa.get('/accounts/password/change/', function (r) {
        aa.post('/accounts/logout/', { csrfmiddlewaretoken: aa.tokenOf(r.text()) }, function () {
          if (path) { aa.token(path, cb); } else if (cb) { cb(); }
        });
      });
    },
    // đăng nhập bằng user/pass từ trạng thái Guest, rồi lấy CSRF của trang path
    login: function (user, pass, path, cb) {
      aa.guest('/accounts/login/', function () {
        aa.post('/accounts/login/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), username: user, password: pass }, function () {
          if (path) { aa.token(path, cb); } else if (cb) { cb(); }
        });
      });
    },
    admin: function (path, cb) { aa.login(pm.variables.get('admin_user'), pm.variables.get('admin_pass'), path, cb); },
    // đăng ký một tài khoản Customer mới (lưu ep_user, ep_email), kết thúc ở trạng thái đã đăng nhập
    newUser: function (path, cb) {
      aa.guest('/accounts/register/', function () {
        var u = aa.uniq('ep'), pw = pm.variables.get('aa_password');
        pm.collectionVariables.set('ep_user', u); pm.collectionVariables.set('ep_email', u + '@example.test');
        aa.post('/accounts/register/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), username: u, email: u + '@example.test', password1: pw, password2: pw }, function () {
          if (path) { aa.token(path, cb); } else if (cb) { cb(); }
        });
      });
    },
    // tạo tài khoản mới rồi về Guest, lấy CSRF của trang path
    newUserGuest: function (path, cb) { aa.newUser(null, function () { aa.guest(path, cb); }); },
    // tạo một tài khoản khác (lưu ep_b_user, ep_b_email), dùng cho ca trùng username / email
    other: function (cb) {
      aa.guest('/accounts/register/', function () {
        var u = aa.uniq('epb'), pw = pm.variables.get('aa_password');
        pm.collectionVariables.set('ep_b_user', u); pm.collectionVariables.set('ep_b_email', u + '@example.test');
        aa.post('/accounts/register/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), username: u, email: u + '@example.test', password1: pw, password2: pw }, function () { cb(); });
      });
    },
    // đọc hộp thư phát triển (cần Admin là superuser) và tìm liên kết đặt lại gửi tới email; cb(null) nếu không có thư
    mailLink: function (email, cb) {
      aa.admin(null, function () {
        aa.get('/dev/mailbox/', function (r) {
          var hit = null;
          r.text().split('<details').forEach(function (b) {
            if (!hit && b.indexOf(email) !== -1) {
              var m = b.match(/\/accounts\/password\/reset\/([^\/\s"<]+)\/([^\/\s"<]+)\//);
              if (m) { hit = { uid: m[1], token: m[2] }; }
            }
          });
          cb(hit);
        });
      });
    },
    // tạo tài khoản mới, yêu cầu đặt lại mật khẩu, mở liên kết trong thư; kết thúc ở Guest, đứng trên form mật khẩu mới
    startReset: function (cb) {
      aa.newUserGuest('/accounts/password/reset/', function () {
        var email = pm.collectionVariables.get('ep_email');
        aa.post('/accounts/password/reset/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), email: email }, function () {
          aa.mailLink(email, function (hit) {
            var uid = hit ? hit.uid : '', tok = hit ? hit.token : '';
            pm.collectionVariables.set('reset_uid', uid); pm.collectionVariables.set('reset_token', tok);
            aa.guest(null, function () {
              aa.get('/accounts/password/reset/' + uid + '/' + tok + '/', function (r) {
                pm.collectionVariables.set('csrf_token', aa.tokenOf(r.text())); cb();
              });
            });
          });
        });
      });
    },
    // đặt mật khẩu mới trên form đặt lại (sau startReset), rồi về Guest
    finishReset: function (cb) {
      var pw = pm.variables.get('new_password');
      aa.post('/accounts/password/reset/' + pm.collectionVariables.get('reset_uid') + '/set-password/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), new_password1: pw, new_password2: pw }, function () { aa.guest(null, cb); });
    }
  };
  return aa;
})()
